802	  private _attachVideoHover(
803	    li: HTMLLIElement,
804	    videoUrl: string,
805	    figure: HTMLElement,
806	  ): void {
807	    const video = document.createElement("video");
808	    video.muted = true;
809	    video.loop = true;
810	    video.playsInline = true;
811	    video.preload = "none";
812	    figure.append(video);
813	
814	    let isHovered = false;
815	    let pendingPlay: Promise<void> | null = null;
816	
817	    const show = (): void => {
818	      if (isHovered) figure.classList.add("is-video-active");
819	    };
820	
821	    const onEnter = (): void => {
822	      isHovered = true;
823	      if (!video.src) {
824	        video.src = videoUrl;
825	        video.load();
826	      }
827	      pendingPlay = video.play().catch(() => undefined);
828	      if (video.readyState >= 3) {
829	        show();
830	      } else {
831	        video.addEventListener("canplay", show, { once: true });
832	      }
833	    };
834	
835	    const safePause = (): void => {
836	      video.pause();
837	      video.currentTime = 0;
838	    };
839	
840	    const onLeave = (): void => {
841	      isHovered = false;
842	      video.removeEventListener("canplay", show);
843	      figure.classList.remove("is-video-active");
844	      const p = pendingPlay;
845	      pendingPlay = null;
846	      if (p !== null) {
847	        void p.then(() => { if (!isHovered) safePause(); });
848	      } else {
849	        safePause();
850	      }
851	    };
852	
853	    li.addEventListener("pointerenter", onEnter);
854	    li.addEventListener("pointerleave", onLeave);
855	
856	    this._videoHoverCleanups.push(() => {
857	      isHovered = false;
858	      video.removeEventListener("canplay", show);
859	      figure.classList.remove("is-video-active");
860	      const p = pendingPlay;
861	      pendingPlay = null;
862	      if (p !== null) {
863	        void p.then(safePause);
864	      } else {
865	        safePause();
866	      }
867	      li.removeEventListener("pointerenter", onEnter);
868	      li.removeEventListener("pointerleave", onLeave);
869	    });
870	  }
